import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { declOfNum, formatDistance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IHikingListItem } from '../../../@types/hikingList.types';

function OneHikingListItem({ item }: { item: IHikingListItem }) {
  return (
    <PohRow>
      <PohCol md={1} sm={2} xs={3} className="text-md-end">
        <PohAva
          width={64}
          colorize
          alt={item.name}
          className="me-3 rounded-circle"
          src={item.ava}
        />
      </PohCol>
      <PohCol md={8} sm={7} xs={9}>
        <div className="d-flex">
          <div className="flex-grow-1">
            <h5 className="mb-0">{item.name}</h5>

            <em className="m-0">{item.description}</em>
            <div className="d-flex align-items-center mb-1" style={{ gap: 6 }}>
              <PohBadge variant={BadgeVariant.Success}>{item.type.name}</PohBadge>
              <PohBadge
                variant={BadgeVariant.Info}
                title={[
                  ['План: ', formatDistance(item.plannedDistance)].join('\t'),
                  ['Факт: ', formatDistance(item.distance)].join('\t'),
                  ['Итог: ', `${round((item.distance / item.plannedDistance) * 100)}%`].join('\t'),
                ].join('\n')}
              >
                {item.distance > 0 && <strong>{formatDistance(item.distance)}</strong>}
                {!item.distance && (
                  <small style={{ opacity: 0.7 }}>{formatDistance(item.plannedDistance)}</small>
                )}
              </PohBadge>
              <PohBadge variant={BadgeVariant.Info}>
                {item.membersCount}{' '}
                {declOfNum(item.membersCount, ['участник', 'участника', 'участников'])}
              </PohBadge>
            </div>
          </div>
        </div>
      </PohCol>
      <PohCol
        md={3}
        sm={{ span: 3, offset: 0 }}
        xs={{ offset: 3 }}
        className="text-start text-md-end justify-content-md-end d-flex flex-column"
      >
        <div className="d-flex justify-content-start justify-content-md-end">
          <small className="text-muted">
            {dateRangeToLocaleString(item.dateStart, item.dateFinish, false)}
          </small>
          <small className="ms-2">
            <PohBadge variant={BadgeVariant.Info} title="Продолжительность">
              {item.duration > 1 && <>{item.duration} дн.</>}
              {item.duration < 1 && <>{(item.duration * 86400) / 60 / 60} ч.</>}
            </PohBadge>
          </small>
        </div>

        <div
          className="mt-auto align-items-center d-flex justify-content-start justify-content-md-end flex-wrap"
          style={{ gap: -3 }}
        >
          {item.members.map((editor) => {
            return (
              <PohAva
                key={editor.id}
                src={editor.photo}
                colorize
                width="1.7em"
                alt={[editor.name, editor.surname].join(' ')}
                title={[editor.name, editor.surname].join(' ')}
              />
            );
          })}
        </div>
      </PohCol>
    </PohRow>
  );
}
export default OneHikingListItem;
